@using System.Linq
@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlogFrontPage>
@{
	Layout = null;
	var posts = Model.Children<BlogPost>().OrderByDescending(p => p.PublishDate).ToList();
}
<!DOCTYPE html>
<html lang="en">
<head>
	<meta charset="utf-8" />
	<meta name="viewport" content="width=device-width, initial-scale=1" />
	<title>@Model.Title</title>
	<link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body class="min-h-screen bg-slate-50 font-sans text-slate-900 antialiased">
	<header class="border-b border-slate-200 bg-white">
		<div class="mx-auto max-w-3xl px-6 py-12">
			<p class="text-sm font-semibold uppercase tracking-widest text-indigo-600">Model Context Protocol</p>
			<h1 class="mt-3 text-4xl font-bold tracking-tight sm:text-5xl">@Model.Title</h1>
			@if (!string.IsNullOrWhiteSpace(Model.Intro))
			{
				<p class="mt-5 max-w-2xl text-lg leading-relaxed text-slate-600">@Model.Intro</p>
			}
		</div>
	</header>

	<main class="mx-auto max-w-3xl px-6 py-12">
		@await Html.GetBlockGridHtmlAsync(Model, "body")

		<section class="mt-16">
			<h2 class="text-2xl font-bold tracking-tight">Latest posts</h2>
			@if (posts.Count == 0)
			{
				<p class="mt-4 text-slate-500">Nothing published yet — check back soon.</p>
			}
			else
			{
				<ul class="mt-8 space-y-10">
					@foreach (var post in posts)
					{
						<li class="flex flex-col gap-5 sm:flex-row">
							@if (post.ListingImage is not null)
							{
								<a href="@post.Url()" class="block w-full shrink-0 overflow-hidden rounded-xl sm:w-56">
									<img src="@post.ListingImage.GetCropUrl(width: 448, height: 300)" alt="@post.Title" class="h-44 w-full object-cover sm:h-40" loading="lazy" />
								</a>
							}
							<div class="min-w-0">
								<time datetime="@post.PublishDate.ToString("yyyy-MM-dd")" class="text-sm font-medium text-slate-500">@post.PublishDate.ToString("d MMMM yyyy")</time>
								<h3 class="mt-1 text-2xl font-semibold leading-snug">
									<a href="@post.Url()" class="hover:text-indigo-600">@post.Title</a>
								</h3>
								<p class="mt-2 leading-relaxed text-slate-600">@post.Excerpt</p>
								<a href="@post.Url()" class="mt-3 inline-block text-sm font-semibold text-indigo-600 hover:underline">Read the post →</a>
							</div>
						</li>
					}
				</ul>
			}
		</section>
	</main>

	<footer class="border-t border-slate-200 bg-white">
		<div class="mx-auto max-w-3xl px-6 py-8 text-sm text-slate-500">
			Written by the team. Photographs from Unsplash.
		</div>
	</footer>
</body>
</html>
