@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlogPost>
@{
	Layout = null;
	var home = Model.AncestorOrSelf<BlogFrontPage>();
	var homeUrl = home?.Url() ?? "/";
}
<!DOCTYPE html>
<html lang="en">
<head>
	<meta charset="utf-8" />
	<meta name="viewport" content="width=device-width, initial-scale=1" />
	<title>@Model.Title — MCP Notes</title>
	<link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body class="min-h-screen bg-slate-50 font-sans text-slate-900 antialiased">
	<header class="border-b border-slate-200 bg-white">
		<div class="mx-auto max-w-3xl px-6 py-8">
			<a href="@homeUrl" class="text-sm font-semibold text-indigo-600 hover:underline">← MCP Notes</a>
			<h1 class="mt-4 text-4xl font-bold tracking-tight sm:text-5xl">@Model.Title</h1>
			<div class="mt-4 flex flex-wrap items-center gap-x-4 gap-y-2 text-sm text-slate-500">
				<time datetime="@Model.PublishDate.ToString("yyyy-MM-dd")">@Model.PublishDate.ToString("d MMMM yyyy")</time>
			</div>
			@if (!string.IsNullOrWhiteSpace(Model.Excerpt))
			{
				<p class="mt-5 max-w-2xl text-lg leading-relaxed text-slate-600">@Model.Excerpt</p>
			}
		</div>
	</header>

	<main class="mx-auto max-w-3xl px-6 py-12">
		<article>
			@if (Model.ListingImage is not null)
			{
				<img src="@Model.ListingImage.GetCropUrl(width: 1400, height: 700)" alt="@Model.Title" class="mb-8 w-full rounded-xl shadow-sm" />
			}

			@await Html.GetBlockGridHtmlAsync(Model, "body")
		</article>

		<nav class="mt-16 border-t border-slate-200 pt-6">
			<a href="@homeUrl" class="text-sm font-semibold text-indigo-600 hover:underline">← All posts</a>
		</nav>
	</main>

	<footer class="border-t border-slate-200 bg-white">
		<div class="mx-auto max-w-3xl px-6 py-8 text-sm text-slate-500">
			Written by the team. Photographs from Unsplash.
		</div>
	</footer>
</body>
</html>

